/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field CurrencyCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineCurrencyCode extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, CurrencyCode);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    SalesLine   salesLine;

    while select salesLine
        group by CurrencyCode
    {
        if (! ret.in(salesLine.CurrencyCode))
        {
            ret.add(salesLine.CurrencyCode);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, CurrencyCode));
    qbr.value(queryValue(_value));
}
